\caption{Construct MPDAG \citep{perkovic2017interpreting, meek1995causal}}
\label{alg: ConstructMPDAG}
\begin{algorithmic}[1]
\State {\bfseries Inputs:} MPDAG $\mathcal{G}$ and Background knowledge $\mathcal{B}$.
\State {\bfseries Output:} MPDAG $\mathcal{G'}$ or FAIL.
\State Let $\mathcal{G'}=\mathcal{G}$;
\While{$\mathcal{B} \neq \emptyset$}
    \State Select an edge $\{S \rightarrow T\}$ in $\mathcal{B}$;
    \State $\mathcal{B} = \mathcal{B} \backslash \{S \rightarrow T\}$;
    \If{$\{S-T\}$ OR $\{S\rightarrow T\}$ is in $\mathcal{G'}$}
        \State Orient $\{S\rightarrow T\}$ in $\mathcal{G'}$;
        \State Orienting edges in $\mathcal{G'}$ following the rules in Figure \ref{fig: orientation_rule} until no edge can be oriented;
    \Else
        \State FAIL;
    \EndIf
\EndWhile
\end{algorithmic}

\citep[Lemma 3.6]{perkovic2017interpreting}
\label{lem: perkovic2017interpreting/Lemma_3.6}
    Let $S$ and $T$ be distinct nodes in an MPDAG $\mathcal{G}$. If $p$ is a b-possibly causal path from $S$ to $T$ in $\mathcal{G}$, then a subsequence $p^*$ of $p$ forms a b-possibly causal unshielded path from $S$ to $T$ in $\mathcal{G}$.

\citep[Corollary 3.4]{perkovic2020identifying} \label{cor: bucket decomposition}
   Let $\mathbf{D}$ be a node set in an MPDAG $\mathcal{G}=(\mathbf{V}, \mathbf{E})$. Then there is a unique partition of $\mathbf{D}$ into $\mathbf{B_1},..., \mathbf{B_k}$, $k \ge 1$ in $\mathcal{G}$, where $\mathbf{B_1},..., \mathbf{B_k}$ are buckets in $\mathcal{G}$. That is
   \begin{itemize}
       \item $\mathbf{D}=\bigcup_{i=1}^{k} \mathbf{B_i}$, and
       \item $\mathbf{B_i} \cap \mathbf{B_j} = \emptyset$, $i,j \in \{1,...,k\}$, $i \ne j$, and
       \item $\mathbf{B_i}$ is a bucket in $\mathbf{D}$ for each $i \in \{1,...,k\}$.
   \end{itemize}

\caption{Partial causal ordering (PCO) \citep[Algorithm 1]{perkovic2020identifying}}
\label{alg: Partial causal ordering (PCO)}
\begin{algorithmic}[1]
\State {\bfseries Inputs:} Node set $\mathbf{D}$ in MPDAG $\mathcal{G}=(\mathbf{V}, \mathbf{E})$. 
\State {\bfseries Output:} An ordered list $\mathbf{B}=(\mathbf{B_1},..., \mathbf{B_k})$, $k \ge 1$ of the bucket decomposition of $\mathbf{D}$ in $\mathcal{G}$.
\State Let $\mathbf{ConComp}$ be the bucket decomposition of $\mathbf{V}$ in $\mathcal{G}$;
\State Let $\mathbf{ConComp}$ be an empty list;
\While{$\mathcal{B} \neq \emptyset$}
    \State Let $\mathbf{C} \in \mathbf{ConComp}$;
    \State Let $\mathbf{\Bar{C}}$ be the set of nodes in $\mathbf{ConComp}$ that are not in $\mathbf{C}$;
    \If{all edges between $\mathbf{C}$ and $\mathbf{\Bar{C}}$ are into $\mathbf{C}$ in $\mathcal{G}$}
        \State Remove $\mathbf{C}$ from $\mathbf{ConComp}$;
        \State Let $\mathbf{B_{*}} = \mathbf{C} \cup \mathbf{D}$;
        \If{$\mathbf{B_{*}} \neq \emptyset$}
            \State Add $\mathbf{B_{*}}$ to the beginning of $\mathbf{B}$;
        \EndIf
    \EndIf
\EndWhile
\end{algorithmic}

