\begin{algorithmic}[1]
\caption{Identify the type of ancestral relation of $S$ with respect to $T$ in an MPDAG \cite[Algorithm 2]{zuo2022counterfactual}}
\label{alg: ancestral relation between X and Y}
\State \textbf{Input:} MPDAG $\mathcal{G}$, two distinct variables $S$ and $T$ in $\mathcal{G}$.
\State \textbf{Output:} The type of ancestral relation between $S$ and $T$.
\State Find the critical set $\mathbf{C}$ of $S$ with respect to $T$ in $\mathcal{G}$ by Algorithm \ref{alg: FindingCriticalSet}.
\If{$|\mathbf{C}|=0$}
    \State \textbf{return} $T$ is a definite non-descendant of $S$.
\EndIf
\If{$S$ has an arrow into $\mathbf{C}$ or $\mathbf{C}$ induces an incomplete subgraph of $\mathcal{G}$}
    \State \textbf{return} $T$ is a definite descendant of $S$.
\EndIf
\State \textbf{return} $T$ is a possible descendant of $S$.
\end{algorithmic}

\caption{Finding the critical set of $S$ with respect to $T$ in an MPDAG \cite[Algorithm 1]{zuo2022counterfactual}}
\label{alg: FindingCriticalSet}
\begin{algorithmic}[1]
\State \textbf{Input:} MPDAG $\mathcal{G}$, two distinct vertices $S$ and $T$ in $\mathcal{G}$.
\State \textbf{Output:} The critical set $\mathbf{C}$ of $S$ with respect to $T$ in $\mathcal{G}$.
\State Initialize $\mathbf{C}=\emptyset$, a waiting queue $\mathcal{Q}=[]$, and a set $\mathcal{H}=\emptyset$,
\For{$\alpha \in sib(S) \cup ch(S)$}
    \State add $(\alpha, S, \alpha)$ to the end of $\mathcal{Q}$,
\EndFor
\While{$\mathcal{Q} \neq \emptyset$}
    \State take the first element $(\alpha, \phi, \tau)$ out of $\mathcal{Q}$ and add it to $\mathcal{H}$;
    \If{$\tau = T$}
        \State {add $\alpha$ to $\mathbf{C}$, and remove from $\mathcal{S}$ all triples where the first element is $\alpha$;}
    \Else
        \For{each node $\beta$ in $\mathcal{G}$}
            \If{$\tau \rightarrow \beta$ or $\tau - \beta$}
                \If{$\tau \rightarrow \beta$ or $\phi$ is not adjacent with $\beta$ or $\tau$ is the endnode}
                    \If{$\beta$ and $S$ are not adjacent}
                        \If{$(\alpha, \tau, \beta) \notin \mathcal{H}$ and $(\alpha, \tau, \beta) \notin \mathcal{Q}$}
                        \State add $(\alpha, \tau, \beta)$ to the end of $\mathcal{Q}$,
                        \EndIf
                    \EndIf
                \EndIf
            \EndIf
        \EndFor
    \EndIf
\EndWhile
\State \textbf{return} $\mathbf{C}$
\end{algorithmic}

