    \begin{equation*}
    TE(\mathbf{a},\mathbf{a'})=P(\hat{Y}=\hat{y}|do(\mathbf{A}=\mathbf{a}))-P(\hat{Y}=\hat{y}|do(\mathbf{A}=\mathbf{a'})).
    \end{equation*}

