    The controlled direct effect of the value change of $\mathbf{A}$ from $\mathbf{a}$ to $\mathbf{a'}$ on $\hat{Y}=\hat{y}$, while fixing all the other variables $\mathbf{X}$ to $\mathbf{x}$ is given by 
    \begin{equation*}
        CDE(\mathbf{a},\mathbf{a'}, \mathbf{x})=P(\hat{Y}=\hat{y}|do(\mathbf{A}=\mathbf{a}, \mathbf{X}=\mathbf{x}))-P(\hat{Y}=\hat{y}|do(\mathbf{A}=\mathbf{a'},\mathbf{X}=\mathbf{x})).
    \end{equation*}

\begin{equation*}
        CDE(\mathbf{a},\mathbf{a'}, \mathbf{x})=P(\hat{Y}=\hat{y}|do(\mathbf{A}=\mathbf{a}, \mathbf{X}=\mathbf{x}))-P(\hat{Y}=\hat{y}|do(\mathbf{A}=\mathbf{a'},\mathbf{X}=\mathbf{x})).
    \end{equation*}

\citep{kilbertus2017avoiding}
    A predictor $\hat{Y}$ exhibits no proxy discrimination based on the proxy $\mathbf{P}$ if for any value that $\mathbf{P}$ can take, 
    \begin{equation*}
    P(\hat{Y}=\hat{y}|do(\mathbf{P}=\mathbf{p}))=P(\hat{Y}=\hat{y}|do(\mathbf{P}=\mathbf{p'})).
    \end{equation*}

\begin{equation*}
    P(\hat{Y}=\hat{y}|do(\mathbf{P}=\mathbf{p}))=P(\hat{Y}=\hat{y}|do(\mathbf{P}=\mathbf{p'})).
    \end{equation*}

\citep{avin2005identifiability}
    Given a causal path set $\pi$, the $\pi$-specific effect of the value change of $\mathbf{A}$ from $\mathbf{a}$ to $\mathbf{a'}$ on $\hat{Y}=\hat{y}$ through $\pi$ is given by
    \begin{equation*}
        PE_{\pi}(\mathbf{a},\mathbf{a'})=P(\hat{Y}=\hat{y}|do(\mathbf{A}=\mathbf{a'}|\pi), do(\mathbf{A}=\mathbf{a}|\Bar{\pi}))-P(\hat{Y}=\hat{y}|do(\mathbf{A}=\mathbf{a})),
    \end{equation*}
    where $P(\hat{Y}=\hat{y}|do(\mathbf{A=a'}|\pi), do(\mathbf{A=a}|\Bar{\pi}))$ represents the post-intervention distribution of $\hat{Y}$ where the effect of intervention $do(\mathbf{A=a'})$ is transmitted only along $\pi$ while the effect of intervention $do(\mathbf{A=a})$ is transmitted along the other paths.

\begin{equation*}
        PE_{\pi}(\mathbf{a},\mathbf{a'})=P(\hat{Y}=\hat{y}|do(\mathbf{A}=\mathbf{a'}|\pi), do(\mathbf{A}=\mathbf{a}|\Bar{\pi}))-P(\hat{Y}=\hat{y}|do(\mathbf{A}=\mathbf{a})),
    \end{equation*}

\citep[Definition 5]{kusner2017counterfactual} \label{def: counterfactual fairness}
    We say the prediction $\hat{Y}$ is counterfactually fair if under any context $\mathbf{X=x}$ and $\mathbf{A=a}$,
    \begin{equation*}\label{eq: counterfactual fairness}
        P(\hat{Y}_{\mathbf{A} \gets \mathbf{a}}(U)=\hat{y}|\mathbf{X=x},\mathbf{A=a})=P(\hat{Y}_{\mathbf{A}\gets{\mathbf{a'}}}(U)=\hat{y}|\mathbf{X=x},\mathbf{A=a}),    
    \end{equation*}
    for all possible value of $\hat{y}$ and any value attainable by $\mathbf{A}$.

\begin{equation*}\label{eq: counterfactual fairness}
        P(\hat{Y}_{\mathbf{A} \gets \mathbf{a}}(U)=\hat{y}|\mathbf{X=x},\mathbf{A=a})=P(\hat{Y}_{\mathbf{A}\gets{\mathbf{a'}}}(U)=\hat{y}|\mathbf{X=x},\mathbf{A=a}),    
    \end{equation*}

\citep{chiappa2019path,wu2019pc}
   Given a factual condition $\mathbf{O=o}$ where $\mathbf{O} \subseteq \{\mathbf{A},\mathbf{X},\hat{Y}\}$ and a causal path set $\pi$, predictor $\hat{Y}$ achieves the path-specific counterfactual fairness if 
   \begin{equation*}
       P(\hat{Y}_{\mathbf{A=a'}|\pi, \mathbf{A=a}|\Bar{\pi}}=\hat{y}|\mathbf{O=o})=P(\hat{Y}_{\mathbf{A=a}}=\hat{y}|\mathbf{O=o}),
   \end{equation*}
   for all possible value of $\hat{y}$ and any value attainable by $\mathbf{A}$.

\begin{equation*}
        P(\hat{Y}_{\mathbf{A=a'}|\pi, \mathbf{A=a}|\Bar{\pi}}=\hat{y}|\mathbf{O=o})=P(\hat{Y}_{\mathbf{A=a}}=\hat{y}|\mathbf{O=o}),
    \end{equation*}

